def _build_interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for mask in range(1 << len(jobs)):
            if mask.bit_count() != k:
                continue
            selected = [jobs[i] for i in range(len(jobs)) if mask & (1 << i)]
            ids = {job["id"] for job in selected}
            if ids & blocked or not mandatory <= ids:
                continue

            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            valid = True
            for job in sorted(selected, key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue

            value = sum(job["value"] for job in selected)
            selected_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "largest" and selected_ids > best_ids) or
                      (tie == "smallest" and selected_ids < best_ids)))):
                best_value = value
                best_ids = selected_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        ordered_names = sorted(names, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        rows_by_version = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }
        domains = []
        for name in names:
            versions = sorted(rows_by_version[name])
            versions = [v for v in versions
                        if v not in blocked.get(name, [])
                        and (name not in pins or pins[name] == v)]
            domains.append([-1] + versions)

        best_vector = None
        best_versions = None
        for values in product(*domains):
            assignment = dict(zip(names, values))
            if any(assignment.get(name, -1) < 0 or
                   not low <= assignment[name] <= high
                   for name, (low, high) in roots.items()):
                continue

            edges = {name: [] for name in names if assignment[name] >= 0}
            valid = True
            for name in edges:
                row = rows_by_version[name][assignment[name]]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    version = assignment[target]
                    if version < 0 or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            # Every installed package must belong to the active dependency closure.
            reachable = set()
            stack = [name for name in roots if assignment[name] >= 0]
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(edges):
                continue

            finished = set()
            active = set()

            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(dep) for dep in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(acyclic(name) for name in edges):
                continue

            vector = tuple(assignment[name] for name in ordered_names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = {name: assignment[name] for name in names
                                 if assignment[name] >= 0}

        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        full_mask = (1 << len(required)) - 1
        visit_bits = {}
        for index, node in enumerate(required):
            visit_bits[node] = visit_bits.get(node, 0) | (1 << index)

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = visit_bits.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                next_mask = mask | visit_bits.get(edge["v"], 0)
                for duration, next_remaining in options:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"],
                                               next_mask, next_remaining))
        return {"arrival": None}
    return solve


